def head(title,desc,css='meridius.css',path='/'):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111310"><title>{title}</title><meta name="description" content="{desc}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta property="og:image" content="https://meridius-ai.vercel.app/assets/house.webp"><link rel="icon" href="/favicon.svg"><link rel="canonical" href="https://meridius-ai.vercel.app{path}"><link rel="stylesheet" href="/assets/{css}"><script src="/assets/site.js" defer></script></head>'''
def nav():
 return '''<a class="skip" href="#main">Skip to content</a><header class="nav"><a class="brand" href="/" aria-label="Meridius home"><span class="mark" aria-hidden="true">m</span>meridius</a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">Menu <span>+</span></button><nav aria-label="Main navigation"><a href="/work/">Selected work</a><a href="/approach/">The approach</a><a href="/investment/">Investment</a><a class="nav-cta" href="/apply/">Let’s build something <span>↗</span></a></nav></header>'''
def footer():
 return f'''<footer class="footer"><div class="footer-top"><a class="brand" href="/"><span class="mark">m</span>meridius</a><p>Small business.<br>Unreasonably good website.</p><a href="mailto:{EMAIL}">Say hello ↗<br><span>{EMAIL}</span></a></div><div class="footer-bottom"><span>© <span data-year>2026</span> Meridius AI</span><span>Independent by design.</span><a href="/privacy/">Privacy</a><a href="/terms/">Project terms</a><a href="#top">Back to top ↑</a></div></footer>'''
def shell(title,desc,content,path='/'):
 return head(title,desc,path=path)+'<body id="top">'+nav()+'<main id="main">'+content+'</main>'+footer()+'</body></html>'
